index 6d5ca9d..7e5d57d 100644
--- a/src/config/loader.rs
+++ b/src/config/loader.rs
@@ -291,6 +291,11 @@ pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
 ///
 /// Returns the raw serde_yaml::Value without deserializing into
 /// BivvyConfig, which allows for deep merging before final parsing.
+///
+/// Empty files (or files containing only comments/document markers)
+/// return an empty mapping so they act as a no-op during merging.
+/// Files with non-trivial content that don't parse to a YAML mapping
+/// return a [`BivvyError::ConfigParseError`].
 pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
     let content = fs::read_to_string(path).map_err(|e| {
         if e.kind() == std::io::ErrorKind::NotFound {
@@ -302,12 +307,56 @@ pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
         }
     })?;

-    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
-        path: path.to_path_buf(),
-        message: e.to_string(),
+    let value: serde_yaml::Value =
+        serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
+            path: path.to_path_buf(),
+            message: e.to_string(),
+        })?;
+
+    match value {
+        serde_yaml::Value::Null => {
+            if has_meaningful_content(&content) {
+                Err(BivvyError::ConfigParseError {
+                    path: path.to_path_buf(),
+                    message: "File contains content that is not a valid YAML mapping".to_string(),
+                })
+            } else {
+                Ok(serde_yaml::Value::Mapping(Default::default()))
+            }
+        }
+        serde_yaml::Value::Mapping(_) => Ok(value),
+        _ => Err(BivvyError::ConfigParseError {
+            path: path.to_path_buf(),
+            message: format!(
+                "Expected a YAML mapping but found {}",
+                yaml_type_name(&value)
+            ),
+        }),
+    }
+}
+
+/// Returns `true` if the content has lines beyond whitespace, comments,
+/// and YAML document markers (`---`, `...`).
+fn has_meaningful_content(content: &str) -> bool {
+    content.lines().any(|line| {
+        let trimmed = line.trim();
+        !trimmed.is_empty() && !trimmed.starts_with('#') && trimmed != "---" && trimmed != "..."
     })
 }

+/// Human-readable name for a YAML value type (for error messages).
+fn yaml_type_name(value: &serde_yaml::Value) -> &'static str {
+    match value {
+        serde_yaml::Value::Null => "null",
+        serde_yaml::Value::Bool(_) => "a boolean",
+        serde_yaml::Value::Number(_) => "a number",
+        serde_yaml::Value::String(_) => "a string",
+        serde_yaml::Value::Sequence(_) => "a sequence",
+        serde_yaml::Value::Mapping(_) => "a mapping",
+        serde_yaml::Value::Tagged(_) => "a tagged value",
+    }
+}
+
 /// Load split-file definitions and return a synthetic YAML value.
 ///
 /// Reads each file in `paths`, wraps its content under `top_key.<stem>`,
@@ -2252,4 +2301,105 @@ workflow:
         assert_eq!(workflow.steps, vec!["fetch"]);
         assert!(config.steps.contains_key("fetch"));
     }
+
+    // --- Invalid config detection tests ---
+
+    #[test]
+    fn parse_config_errors_on_non_mapping_yaml_content() {
+        // A bare scalar (e.g., user accidentally wrote a string, not a mapping)
+        let result = parse_config("just a string", Path::new("test.yml"));
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+        let err = result.unwrap_err().to_string();
+        assert!(
+            err.contains("a string"),
+            "error should mention type: {}",
+            err
+        );
+    }
+
+    #[test]
+    fn parse_config_errors_on_yaml_sequence() {
+        let result = parse_config("- item1\n- item2\n", Path::new("test.yml"));
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+        let err = result.unwrap_err().to_string();
+        assert!(
+            err.contains("sequence"),
+            "error should mention type: {}",
+            err
+        );
+    }
+
+    #[test]
+    fn parse_config_errors_on_explicit_null_content() {
+        // "null" or "~" is valid YAML but not a valid config
+        let result = parse_config("null", Path::new("test.yml"));
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+
+        let result = parse_config("~", Path::new("test.yml"));
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+    }
+
+    #[test]
+    fn parse_config_allows_truly_empty_content() {
+        // Empty file or comments-only is accepted (returns defaults)
+        let config = parse_config("", Path::new("test.yml")).unwrap();
+        assert!(config.app_name.is_none());
+
+        let config = parse_config("# just a comment\n", Path::new("test.yml")).unwrap();
+        assert!(config.app_name.is_none());
+
+        let config = parse_config("---\n", Path::new("test.yml")).unwrap();
+        assert!(config.app_name.is_none());
+    }
+
+    #[test]
+    fn load_config_value_errors_on_non_mapping_content() {
+        let temp = TempDir::new().unwrap();
+        let path = temp.path().join("config.yml");
+        fs::write(&path, "- item1\n- item2").unwrap();
+
+        let result = load_config_value(&path);
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+    }
+
+    #[test]
+    fn load_config_value_returns_empty_mapping_for_empty_file() {
+        let temp = TempDir::new().unwrap();
+        let path = temp.path().join("config.yml");
+        fs::write(&path, "").unwrap();
+
+        let value = load_config_value(&path).unwrap();
+        assert!(value.is_mapping());
+        assert!(value.as_mapping().unwrap().is_empty());
+    }
+
+    #[test]
+    fn load_config_value_errors_on_explicit_null() {
+        let temp = TempDir::new().unwrap();
+        let path = temp.path().join("config.yml");
+        fs::write(&path, "null\n").unwrap();
+
+        let result = load_config_value(&path);
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+    }
+
+    #[test]
+    fn empty_local_override_does_not_destroy_project_config() {
+        let temp = TempDir::new().unwrap();
+        let bivvy_dir = temp.path().join(".bivvy");
+        fs::create_dir_all(&bivvy_dir).unwrap();
+
+        fs::write(
+            bivvy_dir.join("config.yml"),
+            "app_name: MyApp\nsteps:\n  test:\n    command: echo hello\n",
+        )
+        .unwrap();
+
+        // Empty local override — must not destroy the project config
+        fs::write(bivvy_dir.join("config.local.yml"), "# local overrides\n").unwrap();
+
+        let config = load_merged_config(temp.path()).unwrap();
+        assert_eq!(config.app_name, Some("MyApp".to_string()));
+        assert!(config.steps.contains_key("test"));
+    }
 }

