+    // --- Invalid config detection tests ---
+
+    #[test]
+    fn parse_config_errors_on_non_mapping_yaml_content() {
+        // A bare scalar (e.g., user accidentally wrote a string, not a mapping)
+        let result = parse_config("just a string", Path::new("test.yml"));
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+        let err = result.unwrap_err().to_string();
+        assert!(
+            err.contains("a string"),
+            "error should mention type: {}",
+            err
+        );
+    }
+
+    #[test]
+    fn parse_config_errors_on_yaml_sequence() {
+        let result = parse_config("- item1\n- item2\n", Path::new("test.yml"));
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+        let err = result.unwrap_err().to_string();
+        assert!(
+            err.contains("sequence"),
+            "error should mention type: {}",
+            err
+        );
+    }
+
+    #[test]
+    fn parse_config_errors_on_explicit_null_content() {
+        // "null" or "~" is valid YAML but not a valid config
+        let result = parse_config("null", Path::new("test.yml"));
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+
+        let result = parse_config("~", Path::new("test.yml"));
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+    }
+
+    #[test]
+    fn parse_config_allows_truly_empty_content() {
+        // Empty file or comments-only is accepted (returns defaults)
+        let config = parse_config("", Path::new("test.yml")).unwrap();
+        assert!(config.app_name.is_none());
+
+        let config = parse_config("# just a comment\n", Path::new("test.yml")).unwrap();
+        assert!(config.app_name.is_none());
+
+        let config = parse_config("---\n", Path::new("test.yml")).unwrap();
+        assert!(config.app_name.is_none());
+    }
+
+    #[test]
+    fn load_config_value_errors_on_non_mapping_content() {
+        let temp = TempDir::new().unwrap();
+        let path = temp.path().join("config.yml");
+        fs::write(&path, "- item1\n- item2").unwrap();
+
+        let result = load_config_value(&path);
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+    }
+
+    #[test]
+    fn load_config_value_returns_empty_mapping_for_empty_file() {
+        let temp = TempDir::new().unwrap();
+        let path = temp.path().join("config.yml");
+        fs::write(&path, "").unwrap();
+
+        let value = load_config_value(&path).unwrap();
+        assert!(value.is_mapping());
+        assert!(value.as_mapping().unwrap().is_empty());
+    }
+
+    #[test]
+    fn load_config_value_errors_on_explicit_null() {
+        let temp = TempDir::new().unwrap();
+        let path = temp.path().join("config.yml");
+        fs::write(&path, "null\n").unwrap();
+
+        let result = load_config_value(&path);
+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+    }
+
+    #[test]
+    fn empty_local_override_does_not_destroy_project_config() {
+        let temp = TempDir::new().unwrap();
+        let bivvy_dir = temp.path().join(".bivvy");
+        fs::create_dir_all(&bivvy_dir).unwrap();
+
+        fs::write(
+            bivvy_dir.join("config.yml"),
+            "app_name: MyApp\nsteps:\n  test:\n    command: echo hello\n",
+        )
+        .unwrap();
+
+        // Empty local override — must not destroy the project config
+        fs::write(bivvy_dir.join("config.local.yml"), "# local overrides\n").unwrap();
+
+        let config = load_merged_config(temp.path()).unwrap();
+        assert_eq!(config.app_name, Some("MyApp".to_string()));
+        assert!(config.steps.contains_key("test"));
+    }
 }

